from pathlib import Path
import json,re
root=Path('.')
app=(root/'app.js').read_text(encoding='utf-8')
html=(root/'index.html').read_text(encoding='utf-8')
css=(root/'styles.css').read_text(encoding='utf-8')
main=(root/'electron-main.cjs').read_text(encoding='utf-8')
pkg=json.loads((root/'package.json').read_text(encoding='utf-8'))
manifest=json.loads((root/'manifest.json').read_text(encoding='utf-8'))
sw=(root/'service-worker.js').read_text(encoding='utf-8')

# ---------- app persistence safety ----------
app=app.replace("  const CLOUD_EMAIL_KEY = 'clear_choice_cloud_email_v1';\n", "  const CLOUD_EMAIL_KEY = 'clear_choice_cloud_email_v1';\n  const BACKUP_KEY = 'clear_choice_cleaning_manager_backup_v1';\n")
app=app.replace("    updatedAt: new Date().toISOString()\n", "    updatedAt: ''\n", 1)

needle="""  function loadState() {\n    try {\n      const raw = localStorage.getItem(STORAGE_KEY);\n      if (!raw) return defaultState();\n      const parsed = JSON.parse(raw);\n      const base = defaultState();\n      return {\n        ...base,\n        ...parsed,\n        settings: {\n          ...base.settings,\n          ...(parsed.settings || {}),\n          templates: { ...base.settings.templates, ...((parsed.settings || {}).templates || {}) },\n          vehicles: Array.isArray(parsed.settings?.vehicles) ? parsed.settings.vehicles : []\n        },\n        customers: Array.isArray(parsed.customers) ? parsed.customers : [],\n        appointments: Array.isArray(parsed.appointments) ? parsed.appointments : [],\n        textLog: Array.isArray(parsed.textLog) ? parsed.textLog : []\n      };\n    } catch (err) {\n      console.error(err);\n      return defaultState();\n    }\n  }\n"""
replacement="""  function normalizeState(parsed) {\n    const base=defaultState(),src=parsed&&typeof parsed==='object'?parsed:{};\n    return {\n      ...base,...src,\n      settings:{...base.settings,...(src.settings||{}),templates:{...base.settings.templates,...((src.settings||{}).templates||{})},vehicles:Array.isArray(src.settings?.vehicles)?src.settings.vehicles:[]},\n      customers:Array.isArray(src.customers)?src.customers:[],\n      appointments:Array.isArray(src.appointments)?src.appointments:[],\n      textLog:Array.isArray(src.textLog)?src.textLog:[]\n    };\n  }\n  function stateHasBusinessData(s){return !!((s?.customers?.length||0)||(s?.appointments?.length||0)||(s?.textLog?.length||0)||(s?.settings?.ownerName)||(s?.settings?.ownerPhone)||(s?.settings?.vehicles?.length||0)||(s?.quickNotes));}\n  function loadState() {\n    try {\n      const raw=localStorage.getItem(STORAGE_KEY);\n      if(raw)return normalizeState(JSON.parse(raw));\n      const backup=localStorage.getItem(BACKUP_KEY);\n      if(backup)return normalizeState(JSON.parse(backup));\n    } catch(err){console.error(err);}\n    return defaultState();\n  }\n  function writeLocalState(next,{snapshot=true}={}){\n    const serialized=JSON.stringify(next);\n    if(snapshot){const current=localStorage.getItem(STORAGE_KEY);if(current&&current!==serialized){try{const old=JSON.parse(current);if(stateHasBusinessData(old))localStorage.setItem(BACKUP_KEY,current);}catch{}}}\n    localStorage.setItem(STORAGE_KEY,serialized);\n    window.ccStorage?.saveState?.(serialized).catch?.(console.warn);\n  }\n  async function restorePersistentState(){\n    try{\n      if(!window.ccStorage?.loadState)return;\n      const raw=await window.ccStorage.loadState();if(!raw)return;\n      const disk=normalizeState(JSON.parse(raw));\n      if(stateHasBusinessData(disk)&&!stateHasBusinessData(state)){state=disk;writeLocalState(state,{snapshot:false});}\n    }catch(e){console.warn('Persistent state recovery failed',e)}\n  }\n  async function restorePersistentAuth(){\n    try{if(loadAuth()?.access_token||!window.ccStorage?.loadAuth)return;const raw=await window.ccStorage.loadAuth();if(raw){localStorage.setItem(AUTH_KEY,raw);rememberCloudEmail(JSON.parse(raw)?.user?.email||parseJwt(JSON.parse(raw)?.access_token).email);}}catch(e){console.warn('Persistent login recovery failed',e)}\n  }\n"""
if needle not in app: raise SystemExit('loadState block mismatch')
app=app.replace(needle,replacement,1)

app=app.replace("""  function saveState({ cloud = true } = {}) {\n    state.updatedAt = new Date().toISOString();\n    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));\n    renderAll();\n    if (cloud) scheduleCloudPush(true);\n  }\n""","""  function saveState({ cloud = true } = {}) {\n    state.updatedAt=new Date().toISOString();\n    writeLocalState(state);\n    renderAll();\n    if(cloud)scheduleCloudPush(true);\n  }\n""",1)

app=app.replace("function saveAuth(auth){if(auth){localStorage.setItem(AUTH_KEY,JSON.stringify(auth));rememberCloudEmail(auth?.user?.email||parseJwt(auth?.access_token).email);}else localStorage.removeItem(AUTH_KEY);renderCloudStatus();renderAll();hydrateCloudLoginFields();}",
"function saveAuth(auth){if(auth){const raw=JSON.stringify(auth);localStorage.setItem(AUTH_KEY,raw);window.ccStorage?.saveAuth?.(raw).catch?.(console.warn);rememberCloudEmail(auth?.user?.email||parseJwt(auth?.access_token).email);}else{localStorage.removeItem(AUTH_KEY);window.ccStorage?.saveAuth?.('').catch?.(console.warn);}renderCloudStatus();renderAll();hydrateCloudLoginFields();}")

old="""  async function pushCloud() {\n    if(!cloudConfigured()||!loadAuth()?.access_token)return;\n    const auth=loadAuth(),payload=parseJwt(auth.access_token); const userId=payload.sub; if(!userId)throw new Error('Could not identify cloud account.');\n    await apiFetch('app_state?on_conflict=user_id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({user_id:userId,data:state,updated_at:state.updatedAt})});\n    renderCloudStatus();\n  }\n"""
new="""  async function pushCloud({force=false}={}) {\n    if(!cloudConfigured()||!loadAuth()?.access_token)return;\n    if(!force&&!stateHasBusinessData(state)){\n      try{const remote=await pullCloud();if(remote&&stateHasBusinessData(remote.data)){state=normalizeState(remote.data);writeLocalState(state);renderAll();renderCloudStatus();return;}}catch{}\n    }\n    const auth=loadAuth(),payload=parseJwt(auth.access_token);const userId=payload.sub;if(!userId)throw new Error('Could not identify cloud account.');\n    if(!state.updatedAt)state.updatedAt=new Date().toISOString();\n    await apiFetch('app_state?on_conflict=user_id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({user_id:userId,data:state,updated_at:state.updatedAt})});\n    renderCloudStatus();\n  }\n"""
if old not in app: raise SystemExit('pushCloud block mismatch')
app=app.replace(old,new,1)

old="""      const remote=await pullCloud();\n      if(!remote){await pushCloud();return;}\n      const localTime=Date.parse(state.updatedAt||0),remoteTime=Date.parse(remote.data?.updatedAt||remote.updated_at||0);\n      if(remoteTime>localTime){state={...defaultState(),...remote.data};localStorage.setItem(STORAGE_KEY,JSON.stringify(state));renderAll();}\n      else if(localTime>remoteTime) await pushCloud();\n      renderCloudStatus();\n"""
new="""      const remote=await pullCloud();\n      if(!remote){if(stateHasBusinessData(state))await pushCloud({force:true});return;}\n      const remoteState=normalizeState(remote.data),localHas=stateHasBusinessData(state),remoteHas=stateHasBusinessData(remoteState);\n      if(!localHas&&remoteHas){state=remoteState;writeLocalState(state);renderAll();renderCloudStatus();return;}\n      if(localHas&&!remoteHas){await pushCloud({force:true});renderCloudStatus();return;}\n      if(!localHas&&!remoteHas){renderCloudStatus();return;}\n      const localTime=Date.parse(state.updatedAt||0)||0,remoteTime=Date.parse(remoteState.updatedAt||remote.updated_at||0)||0;\n      if(remoteTime>localTime){writeLocalState(state);state=remoteState;writeLocalState(state);renderAll();}\n      else if(localTime>remoteTime)await pushCloud({force:true});\n      renderCloudStatus();\n"""
if old not in app: raise SystemExit('sync inner block mismatch')
app=app.replace(old,new,1)

app=app.replace("localStorage.setItem(STORAGE_KEY,JSON.stringify(state));scheduleCloudPush();","writeLocalState(state);scheduleCloudPush();")
app=app.replace("state=defaultState(); localStorage.removeItem(STORAGE_KEY); saveState({cloud:false}); toast('App reset.');",
                "state=defaultState();localStorage.removeItem(STORAGE_KEY);localStorage.removeItem(BACKUP_KEY);window.ccStorage?.clearState?.().catch?.(console.warn);saveState({cloud:false});toast('App reset.');")
old="""  async function init() {\n    bindEvents();startCloudAutoSync();hydrateCloudLoginFields();\n    if(!isAndroidNative())$$('.android-only').forEach(el=>el.hidden=true);\n    renderAll();loadVehicleYears();\n    if ('serviceWorker' in navigator && location.protocol !== 'file:') navigator.serviceWorker.register('./service-worker.js').catch(console.warn);\n    if (cloudConfigured() && loadAuth()?.access_token) syncCloud().catch(console.warn);\n"""
new="""  async function init() {\n    await restorePersistentState();\n    await restorePersistentAuth();\n    bindEvents();startCloudAutoSync();hydrateCloudLoginFields();\n    if(!isAndroidNative())$$('.android-only').forEach(el=>el.hidden=true);\n    renderAll();loadVehicleYears();\n    if ('serviceWorker' in navigator && location.protocol !== 'file:') navigator.serviceWorker.register('./service-worker.js').catch(console.warn);\n    if (cloudConfigured() && loadAuth()?.access_token) syncCloud({silent:true}).catch(console.warn);\n"""
if old not in app: raise SystemExit('init mismatch')
app=app.replace(old,new,1)

# ---------- professional branding HTML ----------
html=html.replace('<link rel="icon" href="icon.svg" type="image/svg+xml" />','<link rel="icon" href="brand-logo.png" type="image/png" />')
html=html.replace("""      <div class="brand">\n        <div class="brand-mark" aria-hidden="true">CC</div>\n        <div>\n          <strong>Clear Choice</strong>\n          <span>Cleaning Manager</span>\n        </div>\n      </div>""","""      <div class="brand">\n        <img class="brand-logo" src="brand-logo.png" alt="" />\n        <div>\n          <strong>Clear Choice</strong>\n          <span>Cleaning Manager</span>\n        </div>\n      </div>""")
html=html.replace('<div class="mobile-brand"><strong>Clear Choice</strong><span>Cleaning Manager</span></div>', '<div class="mobile-brand"><img src="brand-logo.png" alt="" /><div><strong>Clear Choice</strong><span>Cleaning Manager</span></div></div>')
html=html.replace('<div>\n            <p class="eyebrow" id="todayLabel"></p>\n            <h1 id="greeting">Your cleaning day</h1>\n          </div>', '<div class="dashboard-title-wrap"><img class="page-logo" src="brand-logo.png" alt="" /><div><p class="eyebrow" id="todayLabel"></p><h1 id="greeting">Your cleaning day</h1></div></div>',1)

professional_css=r'''
/* v1.2.3 professional Clear Choice branding */
:root{--accent:#6d5dfc;--accent-2:#0ba9ff;--accent-soft:#f0edff;--panel:#ffffff;--panel-2:#f7f8fc;--text:#17192a;--muted:#6d7389;--border:#e3e6f0;--shadow:0 12px 34px rgba(26,28,49,.08);--sidebar:#111426;--sidebar-2:#191d35}
body{background:linear-gradient(145deg,#f7f8fc 0%,#f2f5fb 55%,#f7f4ff 100%);color:var(--text)}
.sidebar{background:linear-gradient(180deg,var(--sidebar),#15182a 58%,#101321);border-right:1px solid rgba(255,255,255,.06)}
.brand{padding:18px 18px 16px;gap:12px}.brand-logo{width:54px;height:54px;object-fit:contain;filter:drop-shadow(0 6px 16px rgba(83,92,255,.25))}.brand strong{font-size:16px;letter-spacing:-.01em}.brand span{opacity:.72}
.nav{padding:8px 12px}.nav-item{border-radius:10px;margin-bottom:4px;min-height:44px;font-weight:650;color:#d7daeb}.nav-item:hover{background:rgba(255,255,255,.055)}.nav-item.active{background:linear-gradient(90deg,rgba(109,93,252,.25),rgba(11,169,255,.12));box-shadow:inset 3px 0 0 #8f7cff;color:#fff}.nav-item.active span{color:#8fdcff}
.sidebar-foot{border-top:1px solid rgba(255,255,255,.07)}.sync-pill{background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.06);border-radius:10px;padding:9px 10px}
.main{max-width:1500px;margin:0 auto;padding:28px 34px 42px}.page-head{margin-bottom:20px}.page-head h1{font-size:30px;letter-spacing:-.035em}.eyebrow{font-size:11px;letter-spacing:.11em;font-weight:800;color:#6559d8}.dashboard-title-wrap{display:flex;align-items:center;gap:12px}.page-logo{width:48px;height:48px;object-fit:contain;filter:drop-shadow(0 5px 12px rgba(97,83,214,.15))}
.panel,.stat-card,.toolbar{border:1px solid var(--border);box-shadow:var(--shadow);border-radius:13px}.panel{padding:18px}.stat-card{padding:18px;background:linear-gradient(180deg,#fff,#fbfbfe)}.stat-card strong{letter-spacing:-.035em}.stat-card span{color:#626980;font-weight:700}.stat-card small{color:#9297a8}
.primary,.secondary,.ghost,.danger,.button-link,.file-button{border-radius:9px;min-height:40px;font-weight:750;box-shadow:none}.primary{background:linear-gradient(135deg,#6657f4,#348cff);border-color:transparent}.primary:hover{filter:brightness(1.03)}.secondary{background:#fff;border-color:#dfe2ec;color:#292d41}.secondary:hover{background:#f8f8fc}.danger{border-radius:9px}
input,select,textarea{border-radius:9px;border-color:#dfe2ec;background:#fff}.calendar-day{border-radius:10px}.customer-card{border-radius:12px}.appointment-row{border-radius:10px}.badge,.status-pill{border-radius:999px}
.active-work-dialog{border-radius:16px}.active-job-hero{border-radius:12px;background:linear-gradient(135deg,#f6f4ff,#f2f8ff)}.active-action-grid button{border-radius:10px}.active-actions-card{background:linear-gradient(180deg,#fff,#fbfbff)}
.mobile-brand{display:flex;align-items:center;justify-content:center;gap:7px}.mobile-brand img{width:34px;height:34px;object-fit:contain}.mobile-brand>div{display:grid;text-align:left;line-height:1.05}.mobile-brand span{font-size:9px;color:var(--muted);margin-top:3px}.mobile-header{background:rgba(250,251,254,.96)}
@media(max-width:760px){.main{padding:16px 12px 30px}.page-head h1{font-size:26px}.page-logo{width:40px;height:40px}.panel{border-radius:12px}.stat-card{border-radius:11px}.brand-logo{width:50px;height:50px}}
'''
css += '\n'+professional_css+'\n'

# ---------- Electron persistent storage bridge ----------
main="""const { app, BrowserWindow, shell, ipcMain, safeStorage } = require('electron');\nconst path = require('path');\nconst fs = require('fs');\n\nconst dataPath=()=>path.join(app.getPath('userData'),'clear-choice-data.json');\nconst authPath=()=>path.join(app.getPath('userData'),'clear-choice-auth.bin');\nconst backupDir=()=>path.join(app.getPath('userData'),'backups');\nfunction ensureDir(p){fs.mkdirSync(p,{recursive:true});}\nfunction looksPopulated(raw){try{const s=JSON.parse(raw||'{}');return !!((s.customers||[]).length||(s.appointments||[]).length||(s.textLog||[]).length||s.quickNotes||s.settings?.ownerName||s.settings?.ownerPhone||(s.settings?.vehicles||[]).length);}catch{return false}}\nfunction rotateBackup(existing){if(!existing||!looksPopulated(existing))return;ensureDir(backupDir());const stamp=new Date().toISOString().replace(/[:.]/g,'-');fs.writeFileSync(path.join(backupDir(),`clear-choice-${stamp}.json`),existing,'utf8');const files=fs.readdirSync(backupDir()).filter(f=>f.endsWith('.json')).sort().reverse();for(const f of files.slice(12)){try{fs.unlinkSync(path.join(backupDir(),f))}catch{}}}\nfunction atomicWrite(file,content){ensureDir(path.dirname(file));const tmp=file+'.tmp';fs.writeFileSync(tmp,content,'utf8');fs.renameSync(tmp,file)}\n\nipcMain.handle('cc:load-state',()=>{try{return fs.existsSync(dataPath())?fs.readFileSync(dataPath(),'utf8'):''}catch{return ''}});\nipcMain.handle('cc:save-state',(_e,raw)=>{try{const file=dataPath();const old=fs.existsSync(file)?fs.readFileSync(file,'utf8'):'';if(old&&old!==raw)rotateBackup(old);atomicWrite(file,String(raw||''));return true}catch(e){console.error(e);return false}});\nipcMain.handle('cc:clear-state',()=>{try{if(fs.existsSync(dataPath()))rotateBackup(fs.readFileSync(dataPath(),'utf8'));if(fs.existsSync(dataPath()))fs.unlinkSync(dataPath());return true}catch{return false}});\nipcMain.handle('cc:load-auth',()=>{try{if(!fs.existsSync(authPath())||!safeStorage.isEncryptionAvailable())return '';const encrypted=Buffer.from(fs.readFileSync(authPath(),'utf8'),'base64');return safeStorage.decryptString(encrypted)}catch{return ''}});\nipcMain.handle('cc:save-auth',(_e,raw)=>{try{if(!raw){if(fs.existsSync(authPath()))fs.unlinkSync(authPath());return true}if(!safeStorage.isEncryptionAvailable())return false;ensureDir(path.dirname(authPath()));fs.writeFileSync(authPath(),safeStorage.encryptString(String(raw)).toString('base64'),'utf8');return true}catch{return false}});\n\nfunction createWindow() {\n  const win = new BrowserWindow({\n    width: 1360,height: 900,minWidth: 900,minHeight: 650,title: 'Clear Choice Cleaning Manager',autoHideMenuBar: true,\n    webPreferences:{nodeIntegration:false,contextIsolation:true,sandbox:true,preload:path.join(__dirname,'preload.cjs')}\n  });\n  win.webContents.setWindowOpenHandler(({ url }) => {if (/^(https?:|sms:|mailto:|tel:)/i.test(url)) shell.openExternal(url);return { action: 'deny' };});\n  win.webContents.on('will-navigate', (event, url) => {if (!url.startsWith('file:')) {event.preventDefault();if (/^(https?:|sms:|mailto:|tel:)/i.test(url)) shell.openExternal(url);}});\n  win.loadFile(path.join(__dirname, 'index.html'));\n}\napp.whenReady().then(()=>{createWindow();app.on('activate',()=>{if(BrowserWindow.getAllWindows().length===0)createWindow();});});\napp.on('window-all-closed',()=>{if(process.platform!=='darwin')app.quit();});\n"""
preload="""const { contextBridge, ipcRenderer } = require('electron');\ncontextBridge.exposeInMainWorld('ccStorage',{\n  loadState:()=>ipcRenderer.invoke('cc:load-state'),\n  saveState:(raw)=>ipcRenderer.invoke('cc:save-state',raw),\n  clearState:()=>ipcRenderer.invoke('cc:clear-state'),\n  loadAuth:()=>ipcRenderer.invoke('cc:load-auth'),\n  saveAuth:(raw)=>ipcRenderer.invoke('cc:save-auth',raw)\n});\n"""
(root/'preload.cjs').write_text(preload,encoding='utf-8',newline='\n')

pkg['version']='1.2.3'
files=pkg['build']['files']
for f in ['brand-logo.png','preload.cjs']:
    if f not in files: files.append(f)
pkg['build']['win']['icon']='brand-logo.png'
manifest['theme_color']='#17192a';manifest['background_color']='#f7f8fc';manifest['icons']=[{"src":"brand-logo.png","sizes":"512x512","type":"image/png","purpose":"any maskable"}]
sw=sw.replace("const CACHE = 'clear-choice-v1.2';","const CACHE = 'clear-choice-v1.2.3';")
sw=sw.replace("'./icon.svg'","'./brand-logo.png'")

(root/'app.js').write_text(app,encoding='utf-8',newline='\n')
(root/'index.html').write_text(html,encoding='utf-8',newline='\n')
(root/'styles.css').write_text(css,encoding='utf-8',newline='\n')
(root/'electron-main.cjs').write_text(main,encoding='utf-8',newline='\n')
(root/'package.json').write_text(json.dumps(pkg,indent=2)+'\n',encoding='utf-8',newline='\n')
(root/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n',encoding='utf-8',newline='\n')
(root/'service-worker.js').write_text(sw,encoding='utf-8',newline='\n')
print('patched v1.2.3')
